import{_ as a,o as t,c as r,a6 as o,bp as i,bq as s,br as l,bs as n}from"./chunks/framework.DhXJbKDf.js";const b=JSON.parse('{"title":"DSWP Vertical Cards","description":"","frontmatter":{},"headers":[],"relativePath":"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPVerticalCards.md","filePath":"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPVerticalCards.md"}'),c={name:"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPVerticalCards.md"};function d(m,e,h,p,g,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="dswp-vertical-cards" tabindex="-1">DSWP Vertical Cards <a class="header-anchor" href="#dswp-vertical-cards" aria-label="Permalink to “DSWP Vertical Cards”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This pattern creates a responsive grid of vertical cards, each containing an image, heading, description, and a linked call-to-action. It&#39;s ideal for showcasing services, features, or content categories in a visually consistent format.</p><div class="warning custom-block"><p class="custom-block-title">Important Note</p><p>Each pattern consists of several blocks. Only adjust the content and color block settings. The structural settings (padding and margins) are pre-configured for responsiveness. Modifying structural settings may break the pattern.</p></div><h2 id="pattern-components" tabindex="-1">Pattern Components <a class="header-anchor" href="#pattern-components" aria-label="Permalink to “Pattern Components”">​</a></h2><p><img src="'+i+'" alt="Pattern Card"></p><p>Each card consists of the following blocks (numbers correspond to the image above):</p><ol><li><strong>Featured Image</strong> - Full-width image (250px height, object-fit: cover)</li><li><strong>Heading</strong> - Card title (H5)</li><li><strong>Description</strong> - Body text</li><li><strong>Link</strong> - Call-to-action</li></ol><h2 id="layout-options" tabindex="-1">Layout Options <a class="header-anchor" href="#layout-options" aria-label="Permalink to “Layout Options”">​</a></h2><p>The pattern supports 2, 3, or 4 column layouts. Cards automatically stack on mobile devices for optimal readability. <img src="'+s+'" alt="Layout variations"></p><h2 id="common-tasks" tabindex="-1">Common Tasks <a class="header-anchor" href="#common-tasks" aria-label="Permalink to “Common Tasks”">​</a></h2><h3 id="modifying-cards" tabindex="-1">Modifying Cards <a class="header-anchor" href="#modifying-cards" aria-label="Permalink to “Modifying Cards”">​</a></h3><h3 id="to-remove-a-card" tabindex="-1">To Remove a Card <a class="header-anchor" href="#to-remove-a-card" aria-label="Permalink to “To Remove a Card”">​</a></h3><ol><li>Click the ellipses (⋮) next to the card you want to remove</li><li>Select &quot;Delete&quot; <img src="'+l+'" alt="Removing a card"></li></ol><h3 id="to-add-a-card" tabindex="-1">To Add a Card <a class="header-anchor" href="#to-add-a-card" aria-label="Permalink to “To Add a Card”">​</a></h3><ol><li>Click the ellipses (⋮) next to any existing card</li><li>Select &quot;Duplicate&quot; <img src="'+n+'" alt="Adding a card"></li></ol><h3 id="customizing-elements" tabindex="-1">Customizing Elements <a class="header-anchor" href="#customizing-elements" aria-label="Permalink to “Customizing Elements”">​</a></h3><p>Example: Changing the image</p><ol><li>Click on the existing image</li><li>Select &quot;Replace&quot;</li><li>Upload or choose a new image</li><li>The image will automatically resize to fit the card dimensions</li></ol><h2 id="block-documentation" tabindex="-1">Block Documentation <a class="header-anchor" href="#block-documentation" aria-label="Permalink to “Block Documentation”">​</a></h2><p>For detailed instructions on modifying specific blocks, refer to WordPress&#39;s official documentation:</p><ul><li><a href="https://wordpress.com/support/wordpress-editor/blocks/image-block/" target="_blank" rel="noreferrer">Image Block</a></li><li><a href="https://wordpress.com/support/wordpress-editor/blocks/heading-block/" target="_blank" rel="noreferrer">Heading Block</a></li><li><a href="https://wordpress.com/support/wordpress-editor/blocks/paragraph-block/" target="_blank" rel="noreferrer">Paragraph Block</a></li><li><a href="https://wordpress.org/documentation/article/link-block/" target="_blank" rel="noreferrer">Link Block</a></li></ul>',22)])])}const f=a(c,[["render",d]]);export{b as __pageData,f as default};
